 const match = router([...itemRoutes, ...batchRoutes, ...orderRoutes, ...kitchenRoutes, ...planningRoutes, ...safetyRoutes]);

+function requestLanguage(headers) {
+  const header = Object.entries(headers).find(([name]) => name.toLowerCase() === "accept-language")?.[1];
+  const preferences = String(header ?? "").split(",").map((entry) => {
+    const [tag, ...parameters] = entry.trim().toLowerCase().split(";");
+    const quality = parameters.map((parameter) => parameter.trim()).find((parameter) => parameter.startsWith("q="));
+    const value = quality === undefined ? "1" : quality.slice(2);
+    const q = /^(?:0(?:\.\d{0,3})?|1(?:\.0{0,3})?)$/.test(value) ? Number(value) : 0;
+    const lang = /^(en|ko)(?:-[a-z0-9]+)*$/.exec(tag)?.[1];
+    return { lang, q };
+  });
+  return preferences.filter(({ lang, q }) => lang && q > 0)
+    .sort((a, b) => b.q - a.q)[0]?.lang ?? config.defaultLanguage;
+}
